int findMaximizedCapital(int k, int w, vector<int>& pr, vector<int>& cap) {
    int n = pr.size(); vector<pair<int,int>> p(n); for (int i = 0; i < n; i++) p[i] = {cap[i], pr[i]}; sort(p.begin(), p.end());
    priority_queue<int> h; int i = 0;
    while (k--) { while (i < n && p[i].first <= w) h.push(p[i++].second); if (h.empty()) break; w += h.top(); h.pop(); }
    return w;
}
